import os, hashlib

base = r'C:\AI\benchmark\v2\results-umay\sandboxes\umay-ultra-hizli__kapali\term-kopyalar'
 hash_map = {}

for root, dirs, files in os.walk(base):
    for fname in files:
        fpath = os.path.join(root, fname)
        try:
            with open(fpath, 'rb') as f:
                h = hashlib.md5(f.read()).hexdigest()
        except:
            h = 'ERROR'
        rel = os.path.relpath(fpath, base)
        hash_map.setdefault(h, []).append(rel)

# Show only groups with 2+ files
 groups = {k:v for k,v in hash_map.items() if len(v) >= 2}
